-- Synthetic HDSS template demo data (docs/design/hdss/sample_data.json). Not real people.
SELECT ord::int AS record_id,
  'HH-' || lpad((c[1]::int + 1)::text, 3, '0') AS household_id,
  'HDSS template demo'::text AS hdss_site,
  (ARRAY['Iganga','Iganga','Iganga','Mayuge','Mayuge','Mayuge'])[c[2]::int+1] AS district,
  (ARRAY['Kigulu South','Kigulu South','Kigulu South','Bunya','Bunya','Bunya'])[c[2]::int+1] AS county,
  (ARRAY['Bulamagi','Nakigo','Namungalwe','Baitambogwe','Bukooma','Busakira'])[c[2]::int+1] AS subcounty,
  (ARRAY['Bulamagi','Nabitovu','Bukanga','Baitambogwe','Buwaaya','Busakira'])[c[2]::int+1] AS parish,
  (ARRAY['Mutukula','Bukoona','Kisoko','Kabaale','Bulyango','Lugolole'])[c[2]::int+1] AS village,
  (ARRAY[0.572647,0.705298,0.710988,0.499907,0.455026,0.405089]::numeric[])[c[2]::int+1] AS latitude,
  (ARRAY[33.394374,33.459703,33.390564,33.475385,33.567643,33.400541]::numeric[])[c[2]::int+1] AS longitude,
  CASE c[4] WHEN '0' THEN 'Male' ELSE 'Female' END AS sex,
  (ARRAY['65+','45-64','25-44','15-24','5-14','0-4'])[c[3]::int+1] AS age_band,
  (ARRAY['None','Primary','Secondary','Tertiary'])[c[5]::int+1] AS education,
  (ARRAY['Student','None','Trader','Farmer','Employed','Homemaker','Other'])[c[6]::int+1] AS occupation,
  (ARRAY['Single','Married','Divorced','Widowed'])[c[7]::int+1] AS marital_status,
  (ARRAY['None','In-migrant','Out-migrant','Visitor'])[c[8]::int+1] AS migration_type,
  CASE WHEN c[9] = '-1' THEN NULL ELSE (ARRAY['Birth','Death','In-migration','Out-migration'])[c[9]::int+1] END AS event_type,
  (ARRAY['Yes','No'])[c[10]::int+1] AS bednet,
  (ARRAY['Firewood','Charcoal','Gas','Electricity'])[c[12]::int+1] AS cooking_fuel,
  (ARRAY['Tap','Borehole','Well','Other'])[c[13]::int+1] AS water_source,
  CASE WHEN c[14] = '-1' THEN NULL ELSE (ARRAY['Tiled','Iron','Thatched'])[c[14]::int+1] END AS roof,
  (ARRAY['Cement','Earth','Tiled'])[c[15]::int+1] AS floor,
  (ARRAY['Pit latrine','VIP latrine','Flush toilet','None'])[c[16]::int+1] AS toilet,
  CASE WHEN (c[17]::int & 1) > 0 THEN 'Yes' ELSE 'No' END AS has_radio,
  CASE WHEN (c[17]::int & 2) > 0 THEN 'Yes' ELSE 'No' END AS has_tv,
  CASE WHEN (c[17]::int & 4) > 0 THEN 'Yes' ELSE 'No' END AS has_phone,
  CASE WHEN (c[17]::int & 8) > 0 THEN 'Yes' ELSE 'No' END AS has_fridge,
  CASE WHEN (c[17]::int & 16) > 0 THEN 'Yes' ELSE 'No' END AS has_vehicles,
  (DATE '2025-11-01' + c[11]::int) AS record_date,
  -- illustrative six-monthly update rounds on the SINCEP calendar (Oct-Mar / Apr-Sep), from the record date
  CASE WHEN (DATE '2025-11-01' + c[11]::int) < DATE '2026-04-01' THEN 'UC09' WHEN (DATE '2025-11-01' + c[11]::int) < DATE '2026-10-01' THEN 'UC10' ELSE 'UC11' END AS update_cycle
